// Bundle entrypoint.ts into a set of module-name → source
// string records and write them under generated/ as TypeScript
// modules, each default-exporting one record. Consumers spread
// the records into the Worker Loader callback's `modules` field
// without running a build of their own.
//
// Why a record and not a single string? esbuild's bundle: true
// inlines dynamic import() targets too, which dragged the full
// just-bash command surface (python, js-exec, sqlite, curl,
// html-to-markdown, …) into a ~3 MB string. workerd parsed all
// of it on every cold start even though the default ShellWorker
// disables python/javascript/network. With splitting: true the
// dynamic chunks live next to shell.js in the modules table;
// workerd only parses a chunk the first time something imports
// it, so the cold-start cost matches the static-reachable set
// (~650 KB) and optional features stay free until used.
//
// Why several files and not one? Each optional command
// (html-to-markdown, python, sqlite, js-exec, …) carries chunks
// that are only reachable through that command — html-to-markdown's
// domino (~555 KB) dominates the bundle. Splitting them into their
// own generated module, each published at
// @cloudflare/computer/shell/<feature>, lets a consumer select
// commands by import rather than by a build flag: shell-modules.ts
// imports only the core group, so a feature group the consumer
// never imports is unreachable in its module graph and the bundler
// drops the feature's exclusive chunks — and their heavy
// dependencies — from the uploaded Worker. Opting a command in is a
// single import passed to WorkerShellBackend's `commands` option;
// there is no default-on cost and no flag to set.
//
// curl is an optional group like the rest, but its heavy undici
// dependency (~620 KB) is aliased to a throwing stub at bundle time
// (script/undici-stub.mjs) because the Worker backend runs curl on
// the plain-fetch path, never the undici DNS-pinning path — so a
// consumer that imports the curl group gets a working curl without
// undici's bytes.
//
// The generated/ output is gitignored. It's regenerated by the
// computer package's prepare / pretest / pretypecheck scripts
// so any install from this repo or downstream consumer sees a
// fresh bundle matching the source.

import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

import { buildModuleGraph, parseCommandRegistry, partitionModules } from "./partition.mjs";

const here = dirname(fileURLToPath(import.meta.url));
// Script lives at .../backends/worker-shell/script/build-bundle.mjs;
// the bundle target is one level up at .../backends/worker-shell/.
const root = resolve(here, "..");
const outDir = resolve(root, "generated");

// Optional commands whose chunks are worth splitting out so a
// consumer can drop them. Keyed by the feature name used in the
// package subpath (@cloudflare/computer/shell/<feature>); the
// value lists the just-bash command names that pull the feature
// in. A chunk lands in a feature group only when that feature is
// the sole optional owner of it and core can't reach it; anything
// shared with core or with a second feature stays in core so
// dropping one feature never breaks another.
const OPTIONAL_FEATURES = {
  curl: ["curl"],
  "html-to-markdown": ["html-to-markdown"],
  python: ["python3", "python"],
  sqlite: ["sqlite3"],
  "js-exec": ["js-exec", "node"],
  yq: ["yq"],
  file: ["file"],
  xan: ["xan"],
  jq: ["jq"],
};

// Start from a clean generated/ so a group that stops being
// emitted (e.g. curl folded into core) doesn't leave a stale file
// behind. The directory is gitignored and fully regenerated here.
await rm(outDir, { recursive: true, force: true });
await mkdir(outDir, { recursive: true });

// esbuild's code-splitting requires an outdir to compute chunk
// paths against. Use a scratch directory so the build output is
// transient; we read result.outputFiles and never touch disk
// for the .js fragments themselves.
const scratch = await mkdtemp(resolve(tmpdir(), "shell-bundle-"));

let result;
try {
  result = await build({
    entryPoints: { shell: resolve(root, "entrypoint.ts") },
    bundle: true,
    write: false,
    splitting: true,
    outdir: scratch,
    format: "esm",
    target: "es2022",
    platform: "neutral",
    mainFields: ["module", "main"],
    conditions: ["workerd", "worker", "import"],
    // Flat chunk names so the modules table keys stay simple.
    // shell.js holds the entrypoint; everything else lands as
    // chunk-<hash>.js next to it.
    entryNames: "[name]",
    chunkNames: "chunk-[hash]",
    external: [
      // workerd built-ins resolved at runtime.
      "cloudflare:workers",
      "cloudflare:sockets",
      "node:*",
      // Bare node module names that show up via transitive deps;
      // the nodejs_compat polyfill resolves them inside workerd.
      "util",
      "util/types",
      "stream",
      "buffer",
      "path",
      "fs",
      "fs/promises",
      "events",
      "crypto",
      "url",
      "os",
      "assert",
      "querystring",
      "string_decoder",
      // Optional native compression deps just-bash's `tar` command
      // reaches through `await import(...)` blocks wrapped in
      // try/catch. Leaving them external surfaces a clean
      // "module not found" error if a script reaches for one.
      "node-liblzma",
      "@mongodb-js/zstd",
      // seek-bzip is statically imported by just-bash's tar
      // command for .bz2 support. Leaving it external preserves
      // the bare `import seekBzip from "seek-bzip"` in the emitted
      // bundle; SHELL_RUNTIME_MODULES carries a stub the host
      // Worker spreads into the loader's modules table so workerd
      // resolves the import at module load time.
      "seek-bzip",
    ],
    plugins: [
      // curl reaches undici only through just-bash's DNS-pinning
      // connection owner, which the Worker backend never activates:
      // ShellWorker registers curl on the plain-`fetch` path
      // (entrypoint.ts passes a SecureFetch), so just-bash never
      // constructs the pinned undici Agent. just-bash ships
      // pre-bundled, so it imports undici as a hashed relative
      // chunk (./chunks/undici-<hash>.js) rather than the bare
      // "undici" specifier — redirect both to a throwing stub so
      // the real ~620 KB module stays out of the upload while curl
      // itself ships in core.
      {
        name: "exclude-undici",
        setup(pluginBuild) {
          pluginBuild.onResolve(
            { filter: /(^undici$|[/\\]chunks[/\\]undici-[^/\\]*\.js$)/ },
            () => ({ path: resolve(here, "undici-stub.mjs") }),
          );
        },
      },
    ],
    // Treat any stray .node native binding the resolver still
    // surfaces as an empty module. Belt-and-braces for transitive
    // deps that pull in native code through a deeper path.
    loader: { ".node": "empty" },
    // just-bash does `createRequire(import.meta.url)` at module
    // init time. Workerd doesn't populate import.meta.url for
    // string-loaded Dynamic Worker modules, so the call throws.
    // Substitute a stable file URL at bundle time; createRequire
    // is fine with any absolute file URL, and just-bash never
    // actually require()s anything at runtime — the call sites
    // are dead code in the workerd target.
    define: {
      "import.meta.url": JSON.stringify("file:///shell.js"),
    },
    // Emit the module graph as structured data so the partitioner
    // reads import edges (and their static/dynamic kind) from
    // esbuild rather than scraping the emitted source with regexes.
    metafile: true,
  });
} finally {
  // The scratch outdir is only used to anchor relative paths.
  // No files were written (write: false), so removing it is
  // best-effort cleanup of the empty directory.
  await rm(scratch, { recursive: true, force: true });
}

if (!result.outputFiles || result.outputFiles.length === 0) {
  throw new Error("build-bundle: esbuild returned no output");
}

// Collect each emitted file into a modules record keyed by its
// output basename. esbuild writes the entry as shell.js and chunks
// as chunk-<hash>.js per entryNames / chunkNames above; the
// basenames are unique and match the keys the module graph and
// partitioner use.
const modules = {};
for (const file of result.outputFiles) {
  modules[basename(file.path)] = file.text;
}

if (!modules["shell.js"]) {
  throw new Error(
    `build-bundle: expected shell.js in output, got: ${Object.keys(modules).join(", ")}`,
  );
}

// The graph (import edges) comes from esbuild's metafile; command
// identity (which chunks are just-bash commands vs internal
// diagnostics) comes from parsing shell.js's { name, load }
// registry. partitionModules combines the two and throws if any
// optional feature resolves to no command chunk.
const graph = buildModuleGraph(result.metafile.outputs);
const registry = parseCommandRegistry(modules["shell.js"]);
const partition = partitionModules({ graph, registry, optionalFeatures: OPTIONAL_FEATURES });

// Emit one generated file per group. shell-modules.ts imports
// each by its @cloudflare/computer/shell/<group> subpath and
// spreads them back together.
const groupNames = ["core", ...Object.keys(OPTIONAL_FEATURES)];
let totalBytes = 0;
for (const group of groupNames) {
  const names = (partition[group] ?? []).sort();
  const record = {};
  for (const name of names) {
    record[name] = { js: modules[name] };
    totalBytes += modules[name].length;
  }
  const header =
    `// Generated by script/build-bundle.mjs — do not edit.\n` +
    `// Shell modules exclusive to the "${group}" feature group.\n`;
  const body = `export default Object.freeze(${JSON.stringify(
    record,
    null,
    2,
  )}) as Readonly<Record<string, { js: string }>>;\n`;
  await writeFile(resolve(outDir, `${group}.ts`), `${header}\n${body}`);
}

const coreCount = (partition.core ?? []).length;
const mainBytes = modules["shell.js"].length;
const featureSummary = Object.keys(OPTIONAL_FEATURES)
  .map((f) => `${f} ${(partition[f] ?? []).length}`)
  .join(", ");
console.log(
  `Wrote ${outDir} (core ${coreCount} modules, shell.js ${mainBytes} bytes, ` +
    `features: ${featureSummary}, total ${totalBytes} bytes)`,
);
